// Spam Press A — community Workshop demonstration.
// The Workshop automatically creates a panel on the Cheats page.
const panel = document.querySelector('.xp-workshop-widget:last-child .xp-workshop-content');
if (!panel) throw new Error('Workshop cheat panel was not created');
const label = document.createElement('label');
label.style.cssText = 'display:flex;gap:12px;align-items:center;cursor:pointer';
const toggle = document.createElement('input');
toggle.type = 'checkbox';
toggle.style.accentColor = '#ff6c79';
const text = document.createElement('span');
text.textContent = 'Spam Press A (every 350 ms)';
label.append(toggle, text);
const status = document.createElement('p');
status.textContent = 'Idle — connect XLinkPro and enable controller forwarding first.';
panel.append(label, status);
let timer = null;
let busy = false;
async function tick() {
  if (busy) return;
  busy = true;
  try {
    await xlink.command('press A 60');
    status.textContent = 'Sending A every 350 ms';
  } catch (error) {
    status.textContent = 'Error: ' + error.message;
    toggle.checked = false;
    clearInterval(timer);
    timer = null;
  } finally { busy = false; }
}
toggle.addEventListener('change', () => {
  clearInterval(timer);
  timer = null;
  if (toggle.checked) {
    tick();
    timer = setInterval(tick, 350);
  } else status.textContent = 'Stopped';
});
xlink.log('Spam Press A cheat installed. Open Cheats and enable its switch.');
return () => {
  clearInterval(timer);
  toggle.checked = false;
  status.textContent = 'Stopped';
};
